#!/usr/bin/env bash
# Recoil Link rebrand: rewrites Hyperlane's user-facing package names and CLI
# command onto the Recoil Link equivalents. Idempotent: re-run it after every
# upstream merge so new upstream files pick up the rename too.
#
# Deliberately NOT renamed (keeps upstream merges cheap):
#   - Solidity contracts, Rust crate names, internal identifiers
#   - CHANGELOG.md files (upstream release history)
#   - @hyperlane-xyz/registry (external package we still consume)
#   - pnpm-workspace.yaml / pnpm-lock.yaml (lockfile is regenerated by pnpm install)
set -euo pipefail

cd "$(git rev-parse --show-toplevel)"

OLD_SCOPE='@hyperlane-xyz/'
NEW_SCOPE='@recoillink/'
NEW_REPO='https://github.com/recoil-labs/recoil-link'

# Text files tracked by git that mention the old npm scope.
scope_files() {
  git grep -lI -- "$OLD_SCOPE" -- . \
    ':!*CHANGELOG.md' ':!pnpm-lock.yaml' ':!pnpm-workspace.yaml' \
    ':!scripts/recoil-link/*' || true
}

echo "==> npm scope: $OLD_SCOPE -> $NEW_SCOPE (except registry)"
scope_files | xargs -r perl -pi -e 's{\@hyperlane-xyz/(?!registry\b)}{\@recoillink/}g'

echo "==> package.json repository/homepage/bugs"
git ls-files '*package.json' | xargs -r perl -pi -e '
  s{https://github\.com/hyperlane-xyz/hyperlane-monorepo}{'"$NEW_REPO"'}g;
  s{"homepage":\s*"https://www\.hyperlane\.xyz/?"}{"homepage": "'"$NEW_REPO"'"}g;
'

echo "==> CLI command: hyperlane -> rlink"
CLI=typescript/cli
perl -pi -e 's{"hyperlane":\s*"\./bundle/index\.js"}{"rlink": "./bundle/index.js"}; s{"hyperlane":\s*"node \./dist/cli\.js"}{"rlink": "node ./dist/cli.js"}' "$CLI/package.json"
perl -pi -e "s{\.scriptName\('hyperlane'\)}{.scriptName('rlink')}; s{chalk\.blue\('Hyperlane'\)}{chalk.blue('Recoil Link')}" "$CLI/cli.ts"
perl -pi -e 's{/\.hyperlane`}{/.recoil-link`}' "$CLI/src/commands/options.ts"

# Command invocations in CLI sources, tests, docs and examples.
CMDS='avs|config|core|hook|ica|ism|registry|relayer|send|status|strategy|submit|address|message|validator|warp|fork'
git ls-files "$CLI" ':!*CHANGELOG.md' | xargs -r perl -pi -e "
  s#\} hyperlane #} rlink #g;
  s#\bpnpm hyperlane\b#pnpm rlink#g;
  s#(?<![\w./\@-])hyperlane (?=(?:$CMDS)\b)#rlink #g;
"

echo "==> package.json descriptions"
# Keep "<Chain> Hyperlane SDK module": that names the on-chain module, not our brand.
git ls-files "*package.json" | xargs -r perl -pi -e '
  if (/^\s*"description":/) {
    s{\bHyperlane\b(?! SDK module)}{Recoil Link}g;
    s{\b(an|An) Recoil Link\b}{a Recoil Link}g;
    s{the Recoil Link (Network|network|Protocol)}{Recoil Link}g;
  }
'

echo "==> done. Next: pnpm install (regenerates pnpm-lock.yaml)"
